public class Conto {
    private int saldo;

    public void versa(int x) {
        saldo += x;
    }

    public boolean preleva(int x) {
        if (x > saldo) {
            return false;
        }
        saldo -= x;
        return true;
    }
}

public class Main {
    public static void main(String[] args) {
        Conto c = new Conto();
        c.versa(100);
        System.out.println(c.preleva(150));
        System.out.println(c.preleva(40));
    }
}
